#!/usr/bin/env python3
"""Embed the caustic rest page into one TS string.

`test/rest-caustic.html` is the source. The page has no external assets, so
it goes in as is. Run after editing the page.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "test" / "rest-caustic.html"
OUT = ROOT / "src" / "caustic-html.ts"


def main() -> int:
    html = SOURCE.read_text(encoding="utf-8")
    OUT.write_text(
        "// Generated by scripts/embed-caustic.py; edit test/rest-caustic.html instead.\n"
        f"export const CAUSTIC_HTML = {json.dumps(html, ensure_ascii=False)};\n",
        encoding="utf-8",
    )
    print(f"{OUT.relative_to(ROOT)}: {OUT.stat().st_size} bytes")
    return 0


if __name__ == "__main__":
    sys.exit(main())
